/// A row of the "audit_log" table. The repositories read and write it with SQL; a field stays `None` until it is set or read.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AuditLog {
    pub at: Option<chrono::DateTime<chrono::FixedOffset>>,
