//! The repository of the "categories" table, against the test database.

use rust_sql_mysql_decided_offset_optional_repository_commits::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_category(&uow, 1).await;
    let found = uow.categories().get_by_id(stored.id.expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
    assert!(uow.categories().get_by_name(stored.name.clone().expect("name is set")).await.expect("a read").is_some());
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_category(&uow, 1).await;
    factories::add_category(&uow, 2).await;
    let page = uow.categories().list(0, 1).await.expect("a page");
    assert_eq!(2, page.total);
    assert_eq!(1, page.items.len());
}

#[tokio::test]
async fn is_deleted() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_category(&uow, 1).await;
    uow.categories().delete(&stored).await.expect("a delete");
    assert!(uow.categories().get_by_id(stored.id.expect("id is set")).await.expect("a read").is_none());
}

