    let mut entity = new_order(n);
    entity.customer_id = parent0.id;
    uow.orders().insert(entity).await.expect("a stored Order")
}

/// A valid OrderLine that is not stored yet; n makes its unique values differ.
pub fn new_order_line(n: i32) -> OrderLine {
    OrderLine {
